fn main() {
    // Simulate regex by filtering alphanumeric chars
    let text = "Rust1 is2 great3!";
    let words: Vec<&str> = text.split_whitespace()
        .map(|w| w.trim_matches(|c: char| !c.is_alphabetic()))
        .filter(|w| !w.is_empty())
        .collect();
    for w in &words {
        println!("{}", w);
    }
}
